+// ErrRepoFilterUnmatched reports that query-serve answered (the route exists)
+// but the explicit repo filter matched nothing the caller can search — the
+// repo isn't indexed yet, or its owner org isn't enabled on the
+// semantic-search feature flag (entire-search fails closed with a JSON 404,
+// existence not disclosed). A typo'd repo can't produce this from the CLI:
+// the slug was already resolved against the control-plane index before any
+// cell was contacted. Distinct from ErrCellUnavailable so fan-out callers
+// don't misreport a repo-level miss as a region without query-serve.
+var ErrRepoFilterUnmatched = errors.New("no requested repo was found in this cell")
+
 // WildcardQuery is the query string used when only filters are provided (no search terms).
 const WildcardQuery = "*"

@@ -649,9 +659,11 @@ func CellV4(ctx context.Context, client *api.Client, cfg Config, repoIDs []strin

 	q := url.Values{}
 	q.Set("q", cfg.Query)
+	filtered := false
 	for _, id := range repoIDs {
 		if id != "" {
 			q.Add("repo", id)
+			filtered = true
 		}
 	}
 	addCommonSearchParams(q, cfg)
@@ -667,10 +679,25 @@ func CellV4(ctx context.Context, client *api.Client, cfg Config, repoIDs []strin
 		return nil, fmt.Errorf("reading response: %w", err)
 	}
 	if resp.StatusCode == http.StatusNotFound {
-		// The gateway has no semantic-search route (plain "404 page not
-		// found") — query-serve isn't deployed in this cell. Deployed cells
-		// answer unknown repos with an empty 200, so a route-level 404 is
-		// distinctive.
+		// Two distinct 404s share this status. A JSON error body is
+		// query-serve answering through the gateway: the route exists but the
+		// repo filter matched nothing the caller may search (not indexed, or
+		// the owner org isn't flag-enabled — entire-search fails closed,
+		// existence not disclosed). A plain "404 page not found" is the
+		// gateway itself: no semantic-search route, query-serve not deployed
+		// in this cell. Deployed cells answer unfiltered searches of unknown
+		// repos with an empty 200, so the split is unambiguous. The
+		// repo-filter-miss reading only holds when a filter was actually sent
+		// — an unfiltered call named no repo to blame, so its JSON 404
+		// (whatever produced it) degrades to the ErrCellUnavailable fail-safe.
+		var errResp struct {
+			Error string `json:"error"`
+		}
+		if filtered && json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
+			// Wrap rather than return the bare sentinel so the server's own
+			// message survives into debug logs; errors.Is still matches.
+			return nil, fmt.Errorf("%w: %s", ErrRepoFilterUnmatched, errResp.Error)
+		}
 		return nil, ErrCellUnavailable
 	}
 	return parseSearchResponse(resp.StatusCode, body)
diff --git a/cmd/entire/cli/search_v4.go b/cmd/entire/cli/search_v4.go
index 77b2424a..307c70df 100644
--- a/cmd/entire/cli/search_v4.go
+++ b/cmd/entire/cli/search_v4.go
@@ -341,11 +341,18 @@ type semanticCellPage struct {
 // cluster catalog doesn't expose the placement's jurisdiction at all (a cell
 // mid-onboarding). Neither is worth warning the user about on every search.
 func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
-	var skipped []string
+	var skipped, unmatched []string
+	var unmatchedErr error
 	for _, r := range results {
 		switch {
 		case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
 			skipped = append(skipped, r.group.label())
+		case errors.Is(r.err, search.ErrRepoFilterUnmatched):
+			// The cell answered; the repo filter just matched nothing there.
+			// Quiet like a skip when another cell has results, but if NO cell
+			// matches it must surface as a repo problem, never a region one.
+			unmatched = append(unmatched, r.group.label())
+			unmatchedErr = r.err
 		case r.err != nil:
 			lastErr = r.err
 			failed = append(failed, r.group.label())
@@ -365,12 +372,31 @@ func classifySemanticCells(ctx context.Context, results []cellCallResult[*search
 	if len(skipped) > 0 {
 		logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
 	}
-	if len(pages) == 0 && lastErr == nil && len(skipped) > 0 {
-		lastErr = errNoRegionAvailable
+	if len(unmatched) > 0 {
+		// unmatchedErr carries the server's own message (CellV4 wraps it into
+		// the sentinel) — keep it visible here for diagnosis.
+		logging.Debug(ctx, "semantic search: cells where the repo filter matched nothing", "unmatched_cells", unmatched, "error", unmatchedErr.Error())
+	}
+	if len(pages) == 0 && lastErr == nil {
+		switch {
+		case len(unmatched) > 0:
+			// Takes priority over the region message: a cell answering proves
+			// its region serves semantic search.
+			lastErr = errNoRepoAvailable
+		case len(skipped) > 0:
+			lastErr = errNoRegionAvailable
+		}
 	}
 	return pages, failed, lastErr
 }

+// errNoRepoAvailable is returned when at least one cell answered but none
+// matched the repo filter. A typo'd name or missing access cannot reach this
+// point — resolveScope already validated the slug against the control-plane
+// repo index — so the message names only the causes that survive: query-serve
+// hasn't indexed the repo, or its owner org isn't enabled for semantic search.
+var errNoRepoAvailable = errors.New("semantic search cannot search this repo yet — it may not be indexed, or semantic search may not be enabled for its owner")
+
 // errNoRegionAvailable is returned when every queried cell lacks query-serve.
 var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")

