	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return nil, loginHintErr(err)
		}
		return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
	}

	slugs, allRepos := cfg.ScopeSlugs()
	var cells []cellGroup
	var warnings []string
	scoped := !allRepos
	if scoped {
		if len(slugs) == 0 {
